-- 0018: D1 opening data - folios, 300 fleets and the Mandaveli tyre register, taken from the prototype's sample data.
-- GENERATED from "MTC-Depot-Tyre D1.html" (Live Tyre Stock, Tyre Register, HO Fleet Register). All values are the prototype's SAMPLE data.
--  * 19 tyre folios (F7001..), 300 fleets, 528 tyres owned by Mandaveli (fitted / live stock good / repair / at TRS / at MIC).
--  * Fleet Type = the prototype's Small / Standard / Low Floor; stored as the fleet type model, with the HO register "Model" (Ashok Leyland / Tata) as make.
--    Allowed tyre sizes per fleet type are derived from the OEM sizes of its fleets (sample).
--  * The demonstration fleets of batches 6-8 are deactivated (not deleted).
-- Notes while generating:
--   skipped duplicate/blank MTC LM3248
--   skipped duplicate/blank MTC R03904

update public.fleets set status = 'INACTIVE' where is_demo;

-- tyre folios
insert into public.tyre_folios (folio_no, folio_name, specification, construction_type_ref, tube_type_ref, ply, tyre_size_id, product_group_ref, uom_ref)
select v.no, v.name, v.spec, app.ref_id('construction_type', v.cons, 'construction'), app.ref_id('tube_type', v.tube, 'tube'),
       nullif(v.ply, '')::smallint, (select id from public.tyre_sizes where size_code = v.size), app.ref_id('product_group', 'TYRE', 'group'), app.ref_id('uom', 'NOS', 'uom')
from (values
  ('F7001', 'TOLINS EnduRace RA 7.50 X 16', '7.50 X 16 · Tube · Nylon · 16 PR', 'NYLON', 'TUBE', '16', '7.50 X 16'),
  ('F7004', 'CEAT R156 10.00 X 20', '10.00 X 20 · Tube · Radial · 16 PR', 'RADIAL', 'TUBE', '16', '10.00 X 20'),
  ('F7007', 'Apollo Endurace RD 295/80R22.5', '295/80R22.5 · Tubeless · Radial · 16 PR', 'RADIAL', 'TUBELESS', '16', '295/80R22.5'),
  ('F7011', 'CEAT Win Energy XM3 8.25 X 16', '8.25 X 16 · Tube · Radial · 16 PR', 'RADIAL', 'TUBE', '16', '8.25 X 16'),
  ('F7012', 'JK Jetway JUH5 8.25 X 16', '8.25 X 16 · Tube · Nylon · 16 PR', 'NYLON', 'TUBE', '16', '8.25 X 16'),
  ('F7013', 'CEAT EnduRace RA 7.50 X 16', '7.50 X 16 · Tube · Radial · 16 PR', 'RADIAL', 'TUBE', '16', '7.50 X 16'),
  ('F7014', 'CEAT EnduRace RA 10.00 X 20', '10.00 X 20 · Tube · Nylon · 16 PR', 'NYLON', 'TUBE', '16', '10.00 X 20'),
  ('F7015', 'JK Steel Muscle S1R4 10.00 X 20', '10.00 X 20 · Tubeless · Radial · 16 PR', 'RADIAL', 'TUBELESS', '16', '10.00 X 20'),
  ('F7016', 'JK Jetway JUH5 9.00 X 20', '9.00 X 20 · Tube · Nylon · 16 PR', 'NYLON', 'TUBE', '16', '9.00 X 20'),
  ('F7017', 'CEAT Jetway JUH5 295/80R22.5', '295/80R22.5 · Tubeless · Nylon · 16 PR', 'NYLON', 'TUBELESS', '16', '295/80R22.5'),
  ('F7018', 'MRF Steel Muscle S1R4 235/75R17.5', '235/75R17.5 · Tubeless · Radial · 16 PR', 'RADIAL', 'TUBELESS', '16', '235/75R17.5'),
  ('F7019', 'Bridgestone R150 295/90R20', '295/90R20 · Tube · Radial · 16 PR', 'RADIAL', 'TUBE', '16', '295/90R20'),
  ('F7020', 'Apollo Endurace RD 7.50 X 16', '7.50 X 16 · Tubeless · Radial · 16 PR', 'RADIAL', 'TUBELESS', '16', '7.50 X 16'),
  ('F7021', 'CEAT Win Energy XM3 295/80R22.5', '295/80R22.5 · Tube · Radial · 16 PR', 'RADIAL', 'TUBE', '16', '295/80R22.5'),
  ('F7022', 'CEAT Win Energy XM3 9.00 X 20', '9.00 X 20 · Tube · Radial · 16 PR', 'RADIAL', 'TUBE', '16', '9.00 X 20'),
  ('F7023', 'MRF Steel Muscle S1R4 9.00 X 20', '9.00 X 20 · Tubeless · Radial · 16 PR', 'RADIAL', 'TUBELESS', '16', '9.00 X 20'),
  ('F7024', 'CEAT Win Energy XM3 235/75R17.5', '235/75R17.5 · Tube · Radial · 16 PR', 'RADIAL', 'TUBE', '16', '235/75R17.5'),
  ('F7025', 'JK Jetway JUH5 235/75R17.5', '235/75R17.5 · Tube · Nylon · 16 PR', 'NYLON', 'TUBE', '16', '235/75R17.5'),
  ('F7026', 'MRF Steel Muscle S1R4 295/90R20', '295/90R20 · Tubeless · Radial · 16 PR', 'RADIAL', 'TUBELESS', '16', '295/90R20')
) as v(no, name, spec, cons, tube, ply, size)
where not exists (select 1 from public.tyre_folios x where x.folio_no = v.no);

-- makes and models used by the tyres
insert into public.tyre_makes (name)
select m from (values ('JK'), ('CEAT'), ('TOLINS'), ('MRF'), ('Apollo'), ('Bridgestone')) as v(m) where not exists (select 1 from public.tyre_makes x where lower(x.name) = lower(v.m));
insert into public.tyre_models (make_id, model_name)
select (select id from public.tyre_makes where lower(name) = lower(v.make)), v.model
from (values
  ('JK', 'Win Energy XM3'),
  ('JK', 'Steel Muscle S1R4'),
  ('CEAT', 'EnduRace RA'),
  ('JK', 'R156'),
  ('TOLINS', 'EnduRace RA'),
  ('TOLINS', 'R156'),
  ('TOLINS', 'Win Energy XM3'),
  ('TOLINS', 'Jetway JUH5'),
  ('TOLINS', 'Steel Muscle S1R4'),
  ('JK', 'Jetway JUH5'),
  ('MRF', 'Steel Muscle S1R4'),
  ('CEAT', 'Win Energy XM3'),
  ('CEAT', 'R156'),
  ('CEAT', 'Jetway JUH5'),
  ('CEAT', 'Steel Muscle S1R4'),
  ('JK', 'EnduRace RA'),
  ('Apollo', 'EnduRace RA'),
  ('Bridgestone', 'R156'),
  ('MRF', 'Win Energy XM3'),
  ('Apollo', 'Steel Muscle S1R4'),
  ('Bridgestone', 'EnduRace RA'),
  ('MRF', 'EnduRace RA'),
  ('MRF', 'Jetway JUH5'),
  ('Apollo', 'R156'),
  ('Apollo', 'Endurace RD'),
  ('Bridgestone', 'R150')
) as v(make, model)
where not exists (select 1 from public.tyre_models x where x.make_id = (select id from public.tyre_makes where lower(name) = lower(v.make)) and lower(x.model_name) = lower(v.model));

-- fleet types (Small / Standard / Low Floor x make) and their allowed sizes
insert into public.fleet_types (fleet_make, fleet_model)
select v.make, v.model from (values ('Ashok Leyland', 'Small'), ('Tata', 'Small'), ('Tata', 'Standard'), ('Ashok Leyland', 'Standard'), ('Tata', 'Low Floor'), ('Ashok Leyland', 'Low Floor')) as v(make, model)
where not exists (select 1 from public.fleet_types x where lower(x.fleet_make) = lower(v.make) and lower(x.fleet_model) = lower(v.model));
insert into public.fleet_type_tyre_sizes (fleet_type_id, tyre_size_id)
select t.id, s.id from (values ('Ashok Leyland', 'Small', '7.50 X 16'), ('Tata', 'Small', '7.50 X 16'), ('Tata', 'Standard', '10.00 X 20'), ('Ashok Leyland', 'Standard', '10.00 X 20'), ('Tata', 'Low Floor', '10.00 X 20'), ('Ashok Leyland', 'Low Floor', '10.00 X 20'), ('Tata', 'Standard', '295/80R22.5'), ('Ashok Leyland', 'Low Floor', '295/80R22.5'), ('Ashok Leyland', 'Standard', '295/80R22.5'), ('Tata', 'Low Floor', '295/80R22.5')) as v(make, model, size)
join public.fleet_types t on lower(t.fleet_make) = lower(v.make) and lower(t.fleet_model) = lower(v.model)
join public.tyre_sizes s on s.size_code = v.size
on conflict do nothing;

-- fleets
insert into public.fleets (fleet_no, registration_no, chassis_no, purchase_date, org_unit_id, fleet_type_id, bus_model_type_ref, oem_tyre_size_id,
                           operating_status, axle_type, air_type, live_odometer_km, schedule_km, current_route, is_demo)
select v.no, v.reg, nullif(v.chassis, ''), nullif(v.purchase, '')::date,
       (select o.id from public.org_units o where o.unit_type = 'DEPOT' and lower(regexp_replace(o.name, '[^A-Za-z0-9]', '', 'g')) = v.depot),
       (select t.id from public.fleet_types t where lower(t.fleet_make) = lower(v.make) and lower(t.fleet_model) = lower(v.ftype)),
       (select r.id from public.ref_values r where r.list_code = 'bus_model_type' and r.code = nullif(v.mtype, '')),
       (select s.id from public.tyre_sizes s where s.size_code = nullif(v.oem, '')),
